          "title": "Label"
        },
        "max_results": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": 10,
          "description": "Maximum number of results to return.",
          "title": "Max Results"
        },
        "include_spam_trash": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "default": false,
          "description": "Include spam and trash in results.",
          "title": "Include Spam Trash"
        },
        "format": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": "full",
          "description": "Email format to return (\"full\", \"metadata\", \"minimal\", \"raw\").",
          "title": "Format"
